<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import App from '../../../../App.vue';
import WorkBreakControl from '../../../../components/WorkBreakControl.vue';

const NAV = Object.freeze([
  { id: 'Work', label: 'Work', icon: '⌂' },
  { id: 'Performance', label: 'Performance', icon: '◈' },
  { id: 'Timeline', label: 'Timeline', icon: '◷' },
  { id: 'Admin', label: 'Admin', icon: '▦' },
]);
const route = ref(location.hash.slice(1) || 'Work');
const online = ref(typeof navigator === 'undefined' ? true : navigator.onLine);
const darkMode = ref(true); const menuOpen = ref(false); const showWorkBreak = ref(route.value === 'Work' || route.value === '');
const reducedMotion = ref(false); const ambientLightAvailable = ref(false); const driverState = ref('DAY_START');
const activeNav = computed(() => NAV.some(item => item.id === route.value) ? route.value : 'Work');
const fuelVisible = computed(() => ['Work','Performance','Timeline'].includes(activeNav.value));
const stateMeta = computed(() => {
  if (!online.value) return {label:'Offline',className:'offline'};
  const value=String(driverState.value||'DAY_START').toUpperCase();
  const states = { DAY_START:{label:'Ready to start the day',className:'waiting'}, DAY_READY:{label:'Day Ready',className:'waiting'}, SHIFT_WAITING:{label:'Shift Waiting',className:'waiting'}, BUSINESS_TRIP:{label:'On Business Trip',className:'business'}, PERSONAL_TRIP:{label:'Personal trip',className:'personal'}, DAY_ENDED:{label:'Day Ended',className:'waiting'} };
  return states[value] || {label:'Ready to start the day',className:'waiting'};
});
const headerContextLabel = computed(() => activeNav.value !== 'Work' ? activeNav.value : 'Today');
function syncRoute(){route.value=location.hash.slice(1)||'Work';showWorkBreak.value=route.value==='Work'||route.value==='';menuOpen.value=false;}
function navigate(path){const next=String(path||'Work');if(location.hash.slice(1)===next){syncRoute();return;}location.hash=next;}
function goBack(){if(history.length>1)history.back();else navigate('Work');}
function vibrate(pattern=10){try{if('vibrate' in navigator)navigator.vibrate(pattern);}catch{}}
function toggleMenu(){menuOpen.value=!menuOpen.value;vibrate(8);}
function openFuel(){if(!fuelVisible.value)return;window.dispatchEvent(new CustomEvent('kfe:open-fuel'));vibrate(8);}
function setTheme(nextDark){darkMode.value=nextDark;document.documentElement.dataset.kfeTheme=nextDark?'dark':'light';try{localStorage.setItem('kfe:ui-theme',nextDark?'dark':'light')}catch{}}
function detectAmbientLight(){ambientLightAvailable.value='AmbientLightSensor' in globalThis;if(!ambientLightAvailable.value)return;try{const sensor=new AmbientLightSensor({frequency:1});sensor.addEventListener('reading',()=>{if(sensor.illuminance<25)setTheme(true);else if(sensor.illuminance>500)setTheme(false)});sensor.start()}catch{ambientLightAvailable.value=false}}
function restoreTheme(){try{const saved=localStorage.getItem('kfe:ui-theme');if(saved==='light'){setTheme(false);return}if(saved==='dark'){setTheme(true);return}}catch{}const media=globalThis.matchMedia?.('(prefers-color-scheme: dark)');setTheme(media?media.matches:true)}
function handleOnline(){online.value=true} function handleOffline(){online.value=false} function handleDriverState(event){driverState.value=event?.detail?.state||'DAY_START'} function handleKeydown(event){if(event.key==='Escape')menuOpen.value=false}
onMounted(()=>{window.addEventListener('hashchange',syncRoute);window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);window.addEventListener('kfe:driver-state',handleDriverState);window.addEventListener('keydown',handleKeydown);reducedMotion.value=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches??false;restoreTheme();detectAmbientLight()});
onUnmounted(()=>{window.removeEventListener('hashchange',syncRoute);window.removeEventListener('online',handleOnline);window.removeEventListener('offline',handleOffline);window.removeEventListener('kfe:driver-state',handleDriverState);window.removeEventListener('keydown',handleKeydown)});
</script>
<template>
<div class="driver-shell" :data-online="online" :data-reduced-motion="reducedMotion">
<header class="driver-header" aria-label="KFE driver shell"><div class="header-watermark" aria-hidden="true">Kanishka Enterprises</div><div class="header-left"><button class="header-button" type="button" aria-label="Open shell menu" :aria-expanded="menuOpen" @click="toggleMenu">☰</button><button v-if="fuelVisible" class="header-button fuel-button" type="button" aria-label="Quick fuel" @click="openFuel">⛽</button></div><div class="header-context" aria-live="polite"><span class="route-kicker">{{activeNav==='Work'?'Work':activeNav}}</span><strong>{{headerContextLabel}}</strong></div><div class="header-state" :class="`state-${stateMeta.className}`" aria-live="polite"><i v-if="stateMeta.className!=='offline'" aria-hidden="true"></i><b>{{stateMeta.label}}</b></div></header>
<aside v-if="menuOpen" class="shell-menu" aria-label="Shell controls"><div class="menu-title">SHELL</div><button type="button" @click="setTheme(true);menuOpen=false;vibrate(8)"><span>◐</span><b>Dark mode</b><em v-if="darkMode">ACTIVE</em></button><button type="button" @click="setTheme(false);menuOpen=false;vibrate(8)"><span>○</span><b>Light mode</b><em v-if="!darkMode">ACTIVE</em></button><div class="menu-divider"></div><button type="button" @click="goBack();menuOpen=false;vibrate(10)"><span>‹</span><b>Back</b></button><p v-if="!online" class="offline-note">No connection. The app remains available for local work.</p></aside>
<main class="driver-content"><div class="content-surface"><App /></div></main>
<nav class="quick-dock" aria-label="Primary driver navigation"><button v-for="item in NAV" :key="item.id" type="button" :class="{active:activeNav===item.id}" :aria-current="activeNav===item.id?'page':undefined" @click="navigate(item.id);vibrate(8)"><span class="dock-icon" aria-hidden="true">{{item.icon}}</span><strong>{{item.label}}</strong></button></nav>
<div class="system-status" aria-live="polite"><span v-if="ambientLightAvailable">AUTO LIGHT</span></div><WorkBreakControl v-if="showWorkBreak" />
</div></template>
<style scoped>
:global(*),:global(*::before),:global(*::after){box-sizing:border-box}:global(html),:global(body),:global(#app),:global(#vue-runtime){min-height:100%;margin:0}:global(body){background:#080a0d}.driver-shell{--shell-bg:#080a0d;--shell-surface:#101419;--shell-surface-2:#171c22;--shell-border:rgba(255,255,255,.10);--shell-text:#f7f9fb;--shell-muted:#9aa5b1;--shell-accent:#5ee6a8;min-height:100dvh;padding-top:env(safe-area-inset-top);padding-bottom:calc(96px + env(safe-area-inset-bottom));background:var(--shell-bg);color:var(--shell-text);color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:18px;line-height:1.45;overflow-x:hidden}.driver-header{position:fixed;top:0;left:0;right:0;z-index:12000;min-height:76px;padding:10px 14px;padding-top:calc(10px + env(safe-area-inset-top));display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;background:rgba(8,10,13,.96);border-bottom:1px solid var(--shell-border);backdrop-filter:blur(18px) saturate(140%);overflow:hidden}.header-watermark{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none;color:rgba(255,255,255,.045);font-family:Georgia,"Times New Roman",serif;font-size:clamp(1.6rem,7vw,3.5rem);font-style:italic;font-weight:700;letter-spacing:.04em;white-space:nowrap;transform:rotate(-3deg)}.header-left{position:relative;z-index:1;display:flex;align-items:center;gap:7px}.header-button{width:56px;height:56px;min-width:56px;border:1px solid var(--shell-border);border-radius:16px;background:var(--shell-surface);color:var(--shell-text);display:grid;place-items:center;font:inherit;font-size:1.3rem;-webkit-tap-highlight-color:transparent}.fuel-button{color:#f7d774;border-color:rgba(234,179,8,.34);background:rgba(234,179,8,.09)}.header-context{position:relative;z-index:1;display:grid;justify-items:center;line-height:1.08;min-width:0;text-align:center}.route-kicker{color:var(--shell-muted);font-size:.62rem;font-w