v){display:none!important}:deep(.kfe-shell){min-height:auto!important;background:transparent!important;color:inherit!important}:deep(.kfe-viewport){min-height:auto!important}:deep(.kfe-workspace){padding-bottom:0!important}.quick-dock{position:fixed;z-index:12000;left:10px;right:10px;bottom:calc(10px + env(safe-area-inset-bottom));min-height:78px;padding:7px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border:1px solid var(--shell-border);border-radius:24px;background:rgba(16,20,25,.98);box-shadow:0 18px 50px rgba(0,0,0,.38);backdrop-filter:blur(18px) saturate(130%)}.quick-dock button{min-width:0;min-height:64px;border:0;border-radius:18px;background:transparent;color:var(--shell-muted);display:grid;place-items:center;align-content:center;gap:2px;font:inherit}.quick-dock button.active{color:var(--shell-accent);background:rgba(94,230,168,.13)}.dock-icon{font-size:1.35rem;line-height:1}.quick-dock strong{font-size:.68rem;font-weight:900}.system-status{position:fixed;z-index:11900;left:16px;bottom:calc(102px + env(safe-area-inset-bottom));display:flex;align-items:center;gap:10px;pointer-events:none;color:var(--shell-muted);font-size:.62rem;font-weight:850;letter-spacing:.07em;text-transform:uppercase}.system-status span{display:inline-flex;align-items:center;gap:6px}.system-status span:last-child{color:var(--shell-accent)}@media(min-width:760px){.quick-dock{left:50%;right:auto;transform:translateX(-50%);width:min(680px,calc(100vw - 28px))}.system-status{left:max(18px,calc(50% - 330px))}}@media(max-width:560px){.driver-header{grid-template-columns:auto minmax(0,1fr) auto;padding-left:10px;padding-right:10px}.header-button{width:52px;height:52px;min-width:52px}.header-state{padding:0 2px;font-size:.62rem}.header-state b{max-width:84px;overflow:hidden;text-overflow:ellipsis}.header-context strong{font-size:.78rem}.header-watermark{font-size:1.65rem}}@media(prefers-reduced-motion:reduce){.driver-shell *,.driver-shell *::before,.driver-shell *::after{scroll-behavior:auto!important;transition-duration:0s!important;animation-duration:0s!important}}
